"use client";

import Link from "next/link";
import { motion, useMotionValue, useSpring, useTransform } from "motion/react";
import type { Project } from "@/data/site";

/** 作品卡片：鼠标移动时 3D 倾斜 */
export default function ProjectCard({ project }: { project: Project }) {
  const mx = useMotionValue(0.5);
  const my = useMotionValue(0.5);
  const rotateX = useSpring(useTransform(my, [0, 1], [8, -8]), { stiffness: 200, damping: 20 });
  const rotateY = useSpring(useTransform(mx, [0, 1], [-8, 8]), { stiffness: 200, damping: 20 });

  function onMove(e: React.MouseEvent<HTMLDivElement>) {
    const rect = e.currentTarget.getBoundingClientRect();
    mx.set((e.clientX - rect.left) / rect.width);
    my.set((e.clientY - rect.top) / rect.height);
  }

  function onLeave() {
    mx.set(0.5);
    my.set(0.5);
  }

  return (
    <motion.div
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      style={{ rotateX, rotateY, transformPerspective: 900 }}
      whileHover={{ scale: 1.02 }}
      className="group"
    >
      <Link href={`/projects/${project.slug}`} className="block">
        <div
          className={`relative aspect-[4/3] overflow-hidden rounded-2xl bg-gradient-to-br ${project.gradient}`}
        >
          <span className="absolute bottom-4 left-5 text-4xl font-bold text-white/90 transition-transform duration-500 group-hover:-translate-y-1">
            {project.title}
          </span>
          <span className="absolute right-4 top-4 rounded-full bg-white/20 px-3 py-1 text-xs text-white backdrop-blur">
            {project.year}
          </span>
        </div>
        <div className="mt-4 flex items-start justify-between gap-4">
          <p className="text-muted">{project.summary}</p>
          <span className="shrink-0 text-xl transition-transform duration-300 group-hover:translate-x-1 group-hover:-translate-y-1">
            ↗
          </span>
        </div>
        <div className="mt-3 flex flex-wrap gap-2">
          {project.tags.map((t) => (
            <span key={t} className="rounded-full border border-border px-3 py-0.5 text-xs text-muted">
              {t}
            </span>
          ))}
        </div>
      </Link>
    </motion.div>
  );
}
